#include "MirrorSnapshotApi.h"
#include <functional>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace playhub::mirror;
namespace {
unsigned checks{};void Check(bool value,const char* name){++checks;if(!value)throw std::runtime_error(name);}
struct Clock:IClock {Id now=100;Id Now()const noexcept override{return now;}};
struct Authority:IAuthority {bool allowed=true,rendererReady=true;unsigned calls{};std::function<void()> call;bool Current(const SourceLease&)override{++calls;if(call)call();return allowed;}bool RendererReady(const SourceLease&)override{return rendererReady;}};
struct Backend:IBackend {
 bool created{},shown{},attached{},current=true,createOk=true,attachOk=true,showOk=true,hideOk=true,detachOk=true,retireOk=true,destroyOk=true;BandState band=BandState::Ready;unsigned creates{},shows{},attaches{},hides{},retires{},destroys{},currentCalls{};std::function<void()> onCreate,onBand,onAttach,onShow,onCurrent;
 bool CreateHidden(const SourceLease&)override{++creates;created=true;if(onCreate)onCreate();return createOk;}
 BandState PollBand()override{if(onBand)onBand();return band;}
 bool AttachGpu(const SourceLease&)override{++attaches;attached=true;if(onAttach)onAttach();return attachOk;}
 bool ShowNoActivate(const SourceLease&)override{++shows;shown=true;if(onShow)onShow();return showOk;}
 bool Current(const SourceLease&)override{++currentCalls;if(onCurrent)onCurrent();return current;}
 bool Hide()override{++hides;if(hideOk)shown=false;return hideOk;}
 bool DetachGpu()override{if(detachOk)attached=false;return detachOk;}
 bool RetireBand()override{++retires;return retireOk;}
 bool DestroyOwned()override{++destroys;if(destroyOk)created=false;return destroyOk;}
 Id Window()const override{return created?123:0;}Id Cookie()const override{return created?456:0;}bool IsShown()const override{return shown;}bool HasThumbnail()const override{return attached;}
};
SourceLease Lease(Id generation=1){SourceLease l;l.sessionId.fill('a');l.sessionId[64]=0;l.generation=generation;l.gameId=(0x80000001ull<<32)|0x02000000ull;l.expiresAt=10000;l.ownerPid=1;l.ownerBirth=10;l.gamePid=2;l.gameBirth=20;l.framePid=3;l.frameBirth=30;l.frameThread=4;l.sourceThread=5;l.session=1;l.gameWindow=100;l.sourceWindow=200;l.sourceCookie=300;l.gameRect=l.sourceRect={0,0,3840,2160};return l;}
struct Fixture {Clock clock;Authority authority;std::shared_ptr<Backend> backend=std::make_shared<Backend>();Presentation presentation{clock,authority,backend};};
}
int main(){try{
 {Fixture f;auto l=Lease();Check(f.presentation.Begin(l),"authenticated start accepted");Check(!f.presentation.Read().leaseCurrent&&!f.backend->shown,"acceptance is not visibility");f.presentation.Tick();f.presentation.ShowPrepared(l);auto s=f.presentation.Read();Check(s.leaseCurrent&&s.actualScope==1&&s.destinationShown&&s.dwmAttached,"real backend attachment observed without scope2");Check(!s.pixelsVerified&&!s.inputAuthority,"attachment never claims pixels or input authority");f.presentation.Close();s=f.presentation.Read();Check(!s.leaseCurrent&&s.cleanupComplete&&!s.destinationShown&&!s.dwmAttached,"close hides and unregisters");}
 {Fixture f;f.authority.allowed=false;Check(!f.presentation.Begin(Lease())&&f.backend->creates==0,"untrusted caller cannot create");}
 {Fixture f;auto l=Lease();l.sessionId[5]='Z';Check(!f.presentation.Begin(l),"noncanonical session refused");l=Lease();l.gameId=480;Check(!f.presentation.Begin(l),"truncated or unrelated appID refused");l=Lease();l.expiresAt=f.clock.now;Check(!f.presentation.Begin(l),"expired start refused");}
 {Fixture f;auto l=Lease();f.presentation.Begin(l);f.presentation.Close();Check(!f.presentation.Begin(l),"replayed generation refused");for(Id n=2;n<=12;n++){Check(f.presentation.Begin(Lease(n)),"no artificial max2 lifetime");f.presentation.Tick();f.presentation.ShowPrepared(Lease(n));Check(f.presentation.Read().shownCurrent,"reopen attached");f.presentation.Close();}Check(f.backend->shows==11,"one show per authenticated reopen");}
 {Fixture f;f.backend->band=BandState::Pending;f.presentation.Begin(Lease());for(unsigned i=0;i<4;i++)f.presentation.Tick();Check(f.backend->shows==0&&f.backend->attaches==0,"pending callback never presents");f.backend->band=BandState::Ready;f.presentation.Tick();Check(f.presentation.Read().preparedCurrent&&f.backend->shows==0,"completed callback prepares but cannot auto-show");f.presentation.ShowPrepared(Lease());Check(f.backend->shows==1,"renderer-ready receipt permits explicit show");}
 for(unsigned stage=0;stage<5;stage++){Fixture f;auto cancel=[&](){f.presentation.Close();};if(stage==0)f.backend->onCreate=cancel;if(stage==1)f.backend->onBand=cancel;if(stage==2)f.backend->onAttach=cancel;if(stage==3)f.backend->onShow=cancel;if(stage==4)f.backend->onCurrent=cancel;f.presentation.Begin(Lease());f.presentation.Tick();f.presentation.ShowPrepared(Lease());auto s=f.presentation.Read();Check(!s.leaseCurrent&&!f.backend->shown&&!f.backend->attached,"cancel interleaving revokes and cleans partial native work");Check(f.backend->shows==(stage==3?1:0),"no late show after cancellation");}
 {Fixture f;f.backend->onAttach=[&](){f.clock.now=10000;};f.presentation.Begin(Lease());f.presentation.Tick();Check(f.backend->shows==0&&f.presentation.Read().cleanupComplete,"clock recaptured after slow attach prevents expired show");}
 for(unsigned reason=0;reason<3;reason++){Fixture f;f.presentation.Begin(Lease());f.presentation.Tick();f.presentation.ShowPrepared(Lease());if(reason==0)f.backend->current=false;if(reason==1)f.authority.allowed=false;if(reason==2)f.clock.now=10000;f.presentation.Tick();Check(!f.backend->shown&&!f.backend->attached&&!f.presentation.Read().leaseCurrent,"AltTab/source replacement/authority loss/expiry hide");}
 {Fixture f;auto l=Lease();f.presentation.Begin(l);f.presentation.Tick();f.presentation.ShowPrepared(l);auto later=l;later.expiresAt=20000;Check(f.presentation.Renew(later),"same authority renews a caller-chosen expiry");Check(f.presentation.Read().expiresAt==20000,"renewed expiry readback");later.sourceCookie++;Check(!f.presentation.Renew(later),"renew cannot substitute source cookie");later=l;later.gameBirth++;Check(!f.presentation.Renew(later),"renew cannot substitute game birth");later=l;later.generation++;Check(!f.presentation.Renew(later),"renew cannot promote generation");f.clock.now=20000;later=l;later.expiresAt=30000;Check(!f.presentation.Renew(later),"expired authority cannot be revived by renewal");}
 {Fixture f;f.presentation.Begin(Lease());f.presentation.Tick();f.presentation.ShowPrepared(Lease());f.backend->retireOk=false;f.presentation.Close();Check(f.presentation.Read().state==State::CleanupPending&&f.backend->destroys==0,"committed unknown callback retains hidden exact HWND");Check(!f.backend->shown&&!f.presentation.Read().leaseCurrent,"pending cleanup is never active authority");Check(!f.presentation.Begin(Lease(2)),"new authority waits until owned cleanup complete");f.backend->retireOk=true;f.presentation.Tick();Check(f.presentation.Read().cleanupComplete,"cleanup-only tick completes after callback quiescence");}
 {Fixture f;f.presentation.Begin(Lease());f.presentation.Tick();f.presentation.ShowPrepared(Lease());f.backend->hideOk=false;f.presentation.Close();auto s=f.presentation.Read();Check(!s.leaseCurrent&&!s.cleanupComplete&&s.destinationShown,"failed native hide is not reported hidden");f.backend->hideOk=true;f.presentation.Tick();Check(f.presentation.Read().cleanupComplete&&!f.backend->shown,"failed hide retries without new activation");}
 {Fixture f;f.presentation.Begin(Lease());f.presentation.Tick();f.presentation.ShowPrepared(Lease());f.clock.now=10000;auto s=f.presentation.Read();Check(!s.leaseCurrent&&s.actualScope==0&&s.destinationShown&&s.observedAt==100&&s.readAt==10000,"readonly expiry revokes authority but preserves last observed native facts");}
 {Fixture f;f.authority.rendererReady=false;auto l=Lease();f.presentation.Begin(l);f.presentation.Tick();auto s=f.presentation.Read();Check(s.state==State::Prepared&&s.preparedCurrent&&!s.shownCurrent&&!s.destinationShown&&s.dwmAttached&&s.actualScope==1,"cold prepared lease is authenticated hidden composition without scope2");Check(!f.presentation.ShowPrepared(l)&&f.backend->shows==0,"missing renderer receipt never shows");f.authority.rendererReady=true;Check(f.presentation.ShowPrepared(l)&&f.presentation.Read().shownCurrent,"fresh renderer receipt transitions prepared to shown");}
 {Fixture f;auto l=Lease();f.presentation.Begin(l);f.presentation.Tick();f.presentation.Close();Check(!f.presentation.ShowPrepared(l)&&f.backend->shows==0,"Set2 failure cancellation cannot show later");}
 {Fixture f;f.presentation.Close(CloseReason::Disposed);Check(!f.presentation.Begin(Lease()),"disposed session cannot reopen");unsigned before=f.backend->currentCalls;f.presentation.Tick();Check(before==f.backend->currentCalls,"closed component performs no background source poll");}
 {Fixture f;f.presentation.Begin(Lease());Snapshot s;Check(ReadPresentationSnapshot(f.presentation,&s,sizeof(s)),"readonly exact native snapshot");s.version=2;Check(!ReadPresentationSnapshot(f.presentation,&s,sizeof(s)),"unknown ABI rejected");s.version=1;Check(!ReadPresentationSnapshot(f.presentation,&s,sizeof(s)-1),"partial buffer rejected");Check(!ReadPresentationSnapshot(f.presentation,nullptr,sizeof(s)),"null snapshot rejected");}
 {Fixture f;f.authority.call=[&](){f.presentation.Close(CloseReason::Disposed);};Check(!f.presentation.Begin(Lease())&&f.backend->creates==0,"initial authority getter Dispose cannot create after disposal");}
 {Fixture f;f.authority.call=[&](){f.presentation.Close();};Check(!f.presentation.Begin(Lease())&&f.backend->creates==0,"initial getter close revision cannot be ignored");}
 {Fixture f;f.authority.call=[&](){f.clock.now=10000;};Check(!f.presentation.Begin(Lease())&&f.backend->creates==0,"initial authority getter expiry prevents create");}
 {Fixture f;f.authority.call=[](){throw std::runtime_error("unknown issuer");};Check(!f.presentation.Begin(Lease())&&f.backend->creates==0,"throwing initial authority getter fails closed");f.authority.call={};Check(f.presentation.Begin(Lease()),"failed initial getter releases mutation reservation");}
 {Fixture f;auto l=Lease();f.presentation.Begin(l);f.presentation.Tick();f.presentation.ShowPrepared(l);f.authority.call=[&](){f.presentation.Close(CloseReason::Disposed);};l.expiresAt++;Check(!f.presentation.Renew(l)&&!f.presentation.Read().leaseCurrent&&!f.backend->shown,"renew cannot resurrect after reentrant disposal");}
 {Fixture f;f.backend->band=BandState::Pending;auto l=Lease();Check(f.presentation.Begin(l),"admission accepted without waiting callback");auto s=f.presentation.Read();Check(s.state==State::AwaitingBand&&s.generation==l.generation&&s.sourceWindow==l.sourceWindow&&s.destinationWindow==123&&s.destinationCookie==456&&!s.leaseCurrent&&!s.destinationShown&&!s.dwmAttached,"real preparing receipt publishes exact hidden destination before slow band setup");f.presentation.Close();Check(f.backend->shows==0&&f.backend->attaches==0&&f.presentation.Read().cleanupComplete,"cancel admission before first band poll stays hidden");}
 std::cout<<"{\"mirrorLifecycleChecks\":"<<checks<<",\"passed\":true,\"nativeWindowsCreated\":0,\"steamLoaded\":false,\"inputSent\":0}\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
